#!/usr/bin/env bash
# Cowfee Raid Tools test suite: Lua harnesses run with fengari under Node (no Lua runtime needed).
#   bash CRT_Dev/Tests/run_all.sh [addon folder]   defaults to the checkout this script is in
#   ONLY="<group>" bash CRT_Dev/Tests/run_all.sh    one group only (the name after g on its line)
# First run: cd CRT_Dev/Tests && npm install. Prints each group; ends with a summary line and exits 1 on any failure.
W="${1:-$(cd "$(dirname "$0")/../.." && (pwd -W 2>/dev/null || pwd))}"
cd "$(dirname "$0")"
# Every group starts with g <name>: it prints the "== name" line, or skips the group when ONLY names another
# one (test.sh "<name>" sets ONLY, to run one group while working).
g() { [ -z "$ONLY" ] || [ "$1" = "$ONLY" ] || return 1; echo "== $1"; }
for t in "store CRT_Modules/Timeline/Data.lua" "record CRT_Modules/Timeline/Data.lua" "journal CRT_Modules/Timeline/Journal.lua" "reference CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua" "probe CRT_Dev/Dev/TimelineProbe.lua" "lanes CRT_Modules/Timeline/Data.lua CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua CRT_Modules/Timeline/Lanes.lua" "view CRT_Modules/Timeline/Data.lua CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua CRT_Modules/Timeline/Lanes.lua CRT_Modules/Timeline/View.lua" "page CRT_Modules/Timeline/Data.lua CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua CRT_Modules/Timeline/Lanes.lua CRT_Modules/Timeline/ReferencePage.lua CRT_Modules/Timeline/SettingsTab.lua CRT_Modules/Timeline/Page.lua CRT_Modules/Timeline/Journal.lua"; do
  set -- $t; n=$1; shift; case $n in reference|view|page) set -- "$@" CRT_Data/Bosses/Registry.lua CRT_Dev/Tests/SamplePack/Season.lua CRT_Dev/Tests/SamplePack/NekzaliTheSoulcoiler.lua;; esac; [ "$n" = page ] && set -- "$@" CRT_Modules/Timeline/ReviewTab.lua CRT_Modules/Timeline/Rehearsal.lua CRT_Modules/Timeline/RehearsalWindow.lua CRT_Core/Slash.lua; args=""; for f in "$@"; do args="$args \"$W/$f\""; done
  g "$n" && { eval node run_timeline_$n.js $args 2>&1 | tail -${TAIL:-40}; echo "exit ${PIPESTATUS[0]}"; }
done
g "profiles" && { node run_profiles.js "$W/CRT_Core/Profiles.lua" 2>&1 | tail -30; echo "exit ${PIPESTATUS[0]}"; }
g "profiles share" && { node run_profiles_share.js "$W" 2>&1 | tail -40; echo "exit ${PIPESTATUS[0]}"; }
g "settings" && { node run_settings.js "$W" 2>&1 | tail -15; echo "exit ${PIPESTATUS[0]}"; }
WA="$W"
# The grep lints below leave out the test fixtures: files under CRT_Dev/Tests, not any folder named Tests
NOT_TESTS='[/\\]CRT_Dev[/\\]Tests[/\\]'
g "alerts rules" && { node run_alerts_rules.js "$WA/CRT_Modules/Alerts/Rules.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"; }
g "alerts engine" && { node run_alerts_engine.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"; }
g "alerts notes" && { node run_alerts_notes.js old_Engine.lua old_Alert.lua "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Notes/Window.lua" "$WA/CRT_Modules/Notes/Alert.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Areas.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"; }
g "alerts speech" && { node run_alerts_speech.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"; }
