g "alerts special" && { node run_alerts_special.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Special.lua" "$WA/CRT_Dev/Dev/SpecialSample.lua" "$WA/CRT_Data/Bosses/Registry.lua" 2>&1 | tail -20; echo "exit ${PIPESTATUS[0]}"; }
