g "alerts saved" && { node run_alerts_saved.js "$WA/CRT_Core/UI/Panel.lua" "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Draft.lua" "$WA/CRT_Modules/Alerts/SpellLookup.lua" "$WA/CRT_Modules/Alerts/Editor.lua" "$WA/CRT_Modules/Alerts/Saved.lua" "$WA/CRT_Modules/Timeline/View.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"; }
