# The colours from before themes live only in CRT_Core/Themes.lua (the Default: Blizzard palette): code reads CRT.PALETTE. A saved
# colour's default or a data colour that matches one by chance says "not a theme colour" on its line.
g "old Modern colours only in Themes.lua" && { bad=$(grep -rniE '1c1410|2a1f19|4d3c30|70503a|c78f5c|deba8f|f2e6d6|0\.11, *0\.078, *0\.063|0\.165, *0\.122, *0\.098|0\.30?, *0\.235, *0\.188|0\.44, *0\.31, *0\.22|0\.78, *0\.56, *0\.36|0\.87, *0\.73, *0\.56|0\.95, *0\.90?, *0\.84' --include=*.lua --exclude-dir=.claude --exclude-dir=node_modules "$W" | grep -vE "$NOT_TESTS" | grep -v "Themes\.lua:" | grep -v "not a theme colour"); if [ -n "$bad" ]; then echo "FAIL an old Modern colour outside CRT_Core/Themes.lua (read CRT.PALETTE):"; echo "$bad"; else echo "all passed"; fi; }
# The same colours written apart (on and 0.78 or 0.3, on and 0.56 or 0.24, ...): a line holding every part of one.
g "old Modern colours, split" && { bad=""; for t in "0.11 0.078 0.063" "0.165 0.122 0.098" "0.30? 0.235 0.188" "0.30? 0.24 0.19" "0.44 0.31 0.22" "0.78 0.56" "0.87 0.73 0.56" "0.95 0.90? 0.84"; do set -- $t; hits=$(grep -rnE "(^|[^0-9.])$1([^0-9]|$)" --include=*.lua --exclude-dir=.claude --exclude-dir=node_modules "$W" | grep -vE "$NOT_TESTS" | grep -v "Themes.lua:" | grep -v "not a theme colour"); shift; for n in "$@"; do hits=$(echo "$hits" | grep -E "(^|[^0-9.])$n([^0-9]|$)"); done; [ -n "$hits" ] && bad=$(printf '%s\n%s' "$bad" "$hits"); done; if [ -n "$bad" ]; then echo "FAIL an old Modern colour written apart, outside CRT_Core/Themes.lua (read CRT.PALETTE):"; echo "$bad"; else echo "all passed"; fi; }
# Status reds, oranges and greens and heading gold in the modules come from the theme (UI.GoodText, UI.WarnText, UI.BadText,
# UI.HeadingText, UI.Color, UI.Tint "heading"/"good"/"warn"/"bad"; CRT_Dev/StyleGuide.md). Allowed: tooltip lines (the game's
# frame keeps the game's gold) and a line saying "not a theme colour" (the style guide's list of fixed colours).
g "status and heading colours from the theme" && { bad=$(grep -rniE 'ff6060|ff4040|1eff00|ffd100|80ff80|60ff60|40ff40|55dd55|ff8080|ff3030|(cff|")(ff8040|ff8a40|ff8060|ff6040)|(^|[^0-9.])(1, *0\.82, *0|0\.4, *1, *0\.4|1, *0\.3, *0\.3|0\.9, *0\.2, *0\.2|0\.9, *0\.15, *0\.15|0\.3, *0\.85, *0\.3|1, *0\.55, *0\.1|1, *0\.5, *0\.25)([^.0-9]|$)' --include=*.lua "$W/CRT_Modules" | grep -v "GameTooltip" | grep -v "not a theme colour"); if [ -n "$bad" ]; then echo "FAIL a hard-coded status or heading colour in CRT_Modules (use UI.GoodText, UI.WarnText, UI.BadText, UI.HeadingText or UI.Color):"; echo "$bad"; else echo "all passed"; fi; }
g "notes share" && { node run_notes_share.js "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Comm.lua" "$WA/CRT_Modules/Notes/Settings.lua" "$WA/CRT_Modules/Notes/Page.lua" "$WA/CRT_Modules/Notes/Render.lua" 2>&1 | tail -8; echo "exit ${PIPESTATUS[0]}"; }
